import styles from './FormErrorMessage.module.css';

/**
 * Компонент отображения валидационной ошибки поля формы
 *
 * @param {Object} props
 * @param {string} props.name - имя поля (ключ в объекте errors)
 * @param {Object} props.errors - объект ошибок формы (обычно из react-hook-form)
 */
export const FormErrorMessage = ({ name, errors }) => {
  if (!errors?.[name]) return <div className={styles.container} />;

  return (
    <div className={styles.container}>
      <small className={styles.message}>{errors[name].message}</small>
    </div>
  );
};
