import { useEffect, useState } from 'react';
import { useForm } from 'react-hook-form';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';

import { Loading } from '../../../../components/Loading';
import {
  emailValidation,
  nameValidation,
  passwordValidation,
} from '../../../../helpers/validationRules';
import { fetchRegisterRequest, resetRegister } from '../../../../redux/slices/registerSlice';
import {
  Button,
  FormErrorMessage,
  GradientBorderBox,
  gradientList,
  PasswordVisibilityToggle,
} from '@/shared/ui';

import styles from './RegisterForm.module.css';

/**
 * Форма регистрации нового пользователя.
 *
 * Предоставляет интерфейс для ввода имени, email, пароля и согласия на обработку данных.
 * Использует `react-hook-form` для управления формой и валидации, а также
 * Redux для отправки запроса на регистрацию и обработки состояния загрузки и ошибок.
 *
 * После успешной регистрации:
 * - Состояние регистрации сбрасывается.
 * - Форма закрывается через вызов `onClose`.
 *
 * Поддерживает:
 * - Показ/скрытие пароля.
 * - Валидацию на стороне клиента (с помощью предопределённых правил).
 * - Отображение ошибок с сервера (например, email уже занят).
 * - Доступность: переключатель пароля доступен через клавиатуру.
 *
 * @param {Object} props - Входные параметры компонента.
 * @param {() => void} props.onClose - Функция, вызываемая после успешной регистрации
 *                                     для закрытия формы.
 *
 * @component
 * @example
 * <Register onClose={() => setShowForm(false)} />
 *
 * @returns {JSX.Element} Форма регистрации с полями ввода, валидацией и кнопкой отправки.
 *
 * @remarks
 * - Использует `useForm` из `react-hook-form` для управления состоянием формы.
 * - Ошибки с сервера (например, 400 Bad Request) обрабатываются и отображаются в соответствующих полях.
 * - Поле "Согласие" обязательно для заполнения.
 * - Во время отправки формы отображается состояние загрузки.
 * - После успешной регистрации состояние формы сбрасывается.
 */

export const RegisterForm = ({ onClose }) => {
  const { isRegistered, isLoading, errors: error } = useSelector((state) => state.register);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const navigate = useNavigate();
  const dispatch = useDispatch();

  const {
    register,
    handleSubmit,
    setError,
    getValues,
    formState: { errors, isSubmitting },
  } = useForm();

  // Если регистрация успешна — редирект
  useEffect(() => {
    if (isRegistered) {
      dispatch(resetRegister());
      onClose();
    }
  }, [isRegistered, navigate, dispatch]);

  // Если сервер вернул ошибки — показать их через setError
  useEffect(() => {
    if (error) {
      Object.entries(error).forEach(([field, messages]) => {
        setError(field, { type: 'server', message: messages[0] });
      });
    }
  }, [error, setError]);

  // Отправка формы
  const onSubmit = (data) => {
    const { confirmPassword, ...userData } = data; // убираем confirmPassword
    dispatch(fetchRegisterRequest(userData));
  };

  return (
    <>
      {isLoading ? (
        <Loading />
      ) : (
        <div className={styles.wrapper}>
          <div className={styles.container}>
            <h1 className={styles.title}>Создание личного кабинета</h1>
            <form className={styles.regForm} onSubmit={handleSubmit(onSubmit)}>
              {/* Name */}
              <div className={styles.formGroup}>
                <label htmlFor="name" className={styles.formLabel}>
                  Имя пользователя
                </label>
                <div style={{ position: 'relative' }}>
                  <GradientBorderBox
                    gradient={
                      errors.password ? gradientList.input.error : gradientList.input.default
                    }
                  >
                    <input
                      type="text"
                      id="name"
                      {...register('name', nameValidation)}
                      className={`${styles.formInput} ${errors.name ? styles.inputError : ''}`}
                      placeholder="Иван Иванов"
                    />
                  </GradientBorderBox>
                </div>
                <FormErrorMessage name="name" errors={errors} />
              </div>

              {/* Email */}
              <div className={styles.formGroup}>
                <label htmlFor="email" className={styles.formLabel}>
                  Email
                </label>
                <GradientBorderBox
                  gradient={errors.password ? gradientList.input.error : gradientList.input.default}
                >
                  <input
                    type="email"
                    id="email"
                    {...register('email', emailValidation)}
                    className={`${styles.formInput} ${errors.email ? styles.inputError : ''}`}
                    placeholder="example@domain.com"
                  />
                </GradientBorderBox>
                <FormErrorMessage name="email" errors={errors} />
              </div>

              {/* Password */}
              <div className={styles.formGroup}>
                <label htmlFor="password" className={styles.formLabel}>
                  Пароль
                </label>
                <div style={{ position: 'relative' }}>
                  <GradientBorderBox
                    gradient={
                      errors.password ? gradientList.input.error : gradientList.input.default
                    }
                  >
                    <input
                      type={showPassword ? 'text' : 'password'}
                      id="password"
                      {...register('password', passwordValidation)}
                      className={styles.formInput}
                      placeholder="••••••••"
                      autoComplete="new-password"
                    />
                  </GradientBorderBox>

                  {/* Переключатель видимости пароля */}
                  <PasswordVisibilityToggle
                    visible={showPassword}
                    onToggle={() => setShowPassword((v) => !v)}
                  />
                </div>
                <FormErrorMessage name="password" errors={errors} />
              </div>

              {/* Confirm Password */}
              <div className={styles.formGroup}>
                <label htmlFor="confirmPassword" className={styles.formLabel}>
                  Подтвердите пароль
                </label>
                <div style={{ position: 'relative' }}>
                  <GradientBorderBox
                    gradient={
                      errors.password ? gradientList.input.error : gradientList.input.default
                    }
                  >
                    <input
                      type={showConfirmPassword ? 'text' : 'password'}
                      id="confirmPassword"
                      {...register('confirmPassword', {
                        required: 'Требуется подтверждение пароля',
                        validate: (value) =>
                          value === getValues('password') || 'Пароли не совпадают',
                      })}
                      className={`${styles.formInput} ${
                        errors.confirmPassword ? styles.inputError : ''
                      }`}
                      placeholder="••••••••"
                      autoComplete="new-password"
                    />
                  </GradientBorderBox>

                  {/* Переключатель видимости пароля */}
                  <PasswordVisibilityToggle
                    visible={showConfirmPassword}
                    onToggle={() => setShowConfirmPassword((v) => !v)}
                  />
                </div>
                <FormErrorMessage name="confirmPassword" errors={errors} />
              </div>

              {/*Чекбокс согласие с политикой */}
              <div className={`${styles.formGroup} ${styles.consent}`}>
                <div className={styles.checkboxWrapper}>
                  <input
                    type="checkbox"
                    id="consent"
                    className={`${styles.formCheckbox} ${errors.consent ? styles.inputError : ''}`}
                    {...register('consent', { required: 'Требуется согласие' })}
                    aria-invalid={!!errors.consent}
                  />
                  <label htmlFor="consent" className={styles.formLabel}>
                    Я соглашаюсь с политикой в отношении персональных данных
                  </label>
                </div>
                <FormErrorMessage name="consent" errors={errors} />
              </div>

              <GradientBorderBox
                className={styles.gradientBorderBox}
                gradient={gradientList.button.default}
              >
                <Button type="submit" className={styles.registerButton}>
                  Зарегистрироваться
                </Button>
              </GradientBorderBox>
            </form>
          </div>
        </div>
      )}
    </>
  );
};
