import { AnimatePresence, motion } from 'framer-motion';
import { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useLocation, useNavigate } from 'react-router-dom';
import { Link as ScrollLink } from 'react-scroll';

import { LoginForm, RegisterForm } from '@/features/auth/ui';
import { Button, GradientBorderBox, SlidingWrapper } from '@/shared/ui';

import { logout } from '../../../redux/slices/loginSlice';

import styles from './DashboardHeader.module.css';

export const DashboardHeader = () => {
  const isAuthenticated = useSelector((state) => state.login.isAuthenticated);
  const user = useSelector((state) => state.login.user);
  const location = useLocation();
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const isHomePage = location.pathname === '/';

  const [scrollTo, setScrollTo] = useState(null);
  const [activeSection, setActiveSection] = useState('home');
  const [showLoginForm, setShowLoginForm] = useState(false);
  const [showRegisterForm, setShowRegisterForm] = useState(false);
  const isHomeActive = activeSection === 'home';

  useEffect(() => {
    if (!isHomePage) return;

    const handleScroll = () => {
      const sectionIds = menuItemList.map((item) => item.link);
      for (let id of sectionIds) {
        const section = document.getElementById(id);
        if (section) {
          const top = section.getBoundingClientRect().top;
          if (top >= 0 && top <= window.innerHeight / 2) {
            setActiveSection(id);
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [isHomePage]);
  /* Список пунктов меню и их свойств */
  const menuItemList = [
    /*{
      name: "домой",
      link: "home",
      iconClass: styles.navLink,
      visible: true,
    },*/
    {
      name: 'трейды',
      link: 'trades',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'стратегии',
      link: 'strategies',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'технологии',
      link: 'technologies',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'безопасность',
      link: 'safety',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'начать работу',
      link: 'сonnect',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'партнерская программа',
      link: 'affiliateProgram',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      /*
      name: "инвестировать",
      link: "/login",
      iconClass: styles.navLink,
      visible: true,
      isExternal: true*/
    },
  ];

  // Показывать кнопку только на определённом маршруте
  const showButton = location.pathname === '/';

  // Обработчик выхода
  const handleLogout = () => {
    if (isAuthenticated) {
      dispatch(logout());
    }
  };

  // Обработчик выбора пункта меню
  const handleMenuItemClick = (sectionId) => {
    if (sectionId === 'home') {
      setActiveSection('home');
      setScrollTo('home');
      navigate('/');
      return;
    }
    if (location.pathname !== '/') {
      setScrollTo(sectionId);

      navigate('/');
    }
  };

  const handleLoginClick = () => {
    setShowLoginForm(true);
  };

  const [isSticky, setIsSticky] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsSticky(window.scrollY >= 475);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <>
      <div className={`${styles.header} ${isHomePage ? styles.mainColor : ''}`}>
        <div className={`${styles.container}`}>
          <ScrollLink onClick={() => handleMenuItemClick('home')} to={'home'}>
            <div className={`${styles.companyIdentity} ${isHomeActive ? styles.brandActive : ''}`}>
              <div className={styles.logo}>
                <img src="/logo.svg" alt="logo" />
              </div>
            </div>
          </ScrollLink>
          {/* Кнопка входа(кабинет)/инфо клиента */}
          {isAuthenticated ? (
            <div className={styles.userInformation}>
              <div className={styles.userPhoto}>
                <img src="/icon/userPhoto.svg" alt="userPhoto" />
              </div>
              <h3 className={styles.userName}>{user.name}</h3>
            </div>
          ) : showButton ? (
            <GradientBorderBox
              className={styles.cabinetButtonBorder}
              gradient={
                showLoginForm
                  ? 'linear-gradient(#5B5B5B)'
                  : 'linear-gradient(150deg, #E6FBFF 7.28%, #A7770E 81.61%)'
              }
            >
              <Button
                type="submit"
                className={styles.cabinetButton}
                style={{
                  color: showLoginForm ? '#5B5B5B' : undefined,
                }}
                onClick={handleLoginClick}
              >
                кабинет
              </Button>
            </GradientBorderBox>
          ) : null}
        </div>
        <div className={styles.mainMenu}>
          {/* Меню навигации */}
          <nav className={styles.navigation}>
            <div style={{ position: 'relative', display: 'flex' }}>
              <AnimatePresence>
                {menuItemList
                  .filter((item) => item.visible)
                  .map((item) => {
                    const isActive = item.link === activeSection;
                    return !user ? (
                      <ScrollLink
                        key={item.name}
                        className={styles.navLink}
                        onClick={() => handleMenuItemClick(item.link)}
                        to={item.link}
                        smooth={true}
                        offset={-130}
                        duration={800}
                      >
                        <div style={{ position: 'relative' }}>
                          <motion.span
                            animate={{ color: isActive ? '#ffc62e' : '#F4F4F4' }}
                            transition={{ duration: 0.3 }}
                          >
                            {item.name}
                          </motion.span>

                          {isActive && (
                            <motion.div
                              layoutId="underline"
                              className={styles.underline}
                              initial={false}
                              animate={{ opacity: 1 }}
                              exit={{ opacity: 0 }}
                              transition={{ duration: 0.3 }}
                            />
                          )}
                        </div>
                      </ScrollLink>
                    ) : null;
                  })}
              </AnimatePresence>
            </div>
          </nav>
          {isAuthenticated ? (
            <>
              {/* Кнопка выхода */}
              <button className={styles.logoutButton} onClick={handleLogout}>
                выйти
              </button>{' '}
            </>
          ) : null}
        </div>
      </div>

      {showButton && (
        <button
          className={isSticky ? styles.stickyInvestButton : styles.investButton}
          onClick={handleLoginClick}
        >
          Инвестировать
        </button>
      )}
      {/* Формы входа и регистрации */}
      <SlidingWrapper isOpen={showLoginForm} onClose={() => setShowLoginForm(false)}>
        <LoginForm
          onClose={() => setShowLoginForm(false)}
          onRegisterClick={() => {
            setShowLoginForm(false); // Закрыть форму логина
            setShowRegisterForm(true); // Открыть регистрацию
          }}
        />
      </SlidingWrapper>
      <SlidingWrapper isOpen={showRegisterForm} onClose={() => setShowRegisterForm(false)}>
        <RegisterForm onClose={() => setShowRegisterForm(false)} />
      </SlidingWrapper>
    </>
  );
};
