import React from 'react';

import styles from './FileDownloader.module.css';

const DownloadIcon = () => (
  <svg width="32" height="32" viewBox="0 0 24 24" fill="none">
    <path
      d="M12 4v12m0 0l-5-5m5 5l5-5"
      stroke="#fff"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
    <rect x="4" y="20" width="16" height="2" rx="1" fill="#fff" opacity="0.3" />
  </svg>
);

export function FileDownloader({ url, fileName }) {
  const handleDownload = async () => {
    try {
      console.log('TOKEN:', localStorage.getItem('token'));
      const response = await fetch(url, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
      });
      if (!response.ok) throw new Error('Ошибка при скачивании файла');

      const blob = await response.blob();
      const downloadUrl = window.URL.createObjectURL(blob);

      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = fileName || 'file';
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(downloadUrl);
    } catch (e) {
      alert('Ошибка при скачивании файла');
    }
  };

  return (
    <button className={styles.downloadBtn} onClick={handleDownload} title="Скачать файл">
      <DownloadIcon />
    </button>
  );
}
