import React, { useState } from 'react';

import styles from './ToggleTabs.module.css';

export const ToggleTabs = ({ options = [], onChange }) => {
  const [selected, setSelected] = useState(0);

  const handleClick = (index) => {
    setSelected(index);
    if (onChange) onChange(options[index]);
  };

  return (
    <div className={styles.toggleTabs}>
      {options.map((option, index) => (
        <button
          key={option}
          className={`${styles.tabButton} ${selected === index ? styles.active : ''}`}
          onClick={() => handleClick(index)}
        >
          <span className={styles.tabTaxt}>{option}</span>
        </button>
      ))}
    </div>
  );
};
