const API_KEY = '';

export function fetchBTCYearData() {
  const url = `https://min-api.cryptocompare.com/data/v2/histoday?fsym=BTC&tsym=USD&limit=365`;

  return fetch(url, {
    headers: {
      authorization: `Apikey ${API_KEY}`,
    },
  })
    .then((res) => {
      if (!res.ok) {
        throw new Error(`HTTP error! Status: ${res.status}`);
      }
      return res.json();
    })
    .then((data) => {
      return data;
    })
    .catch((error) => {
      console.error('Ошибка при получении данных BTC:', error);
      return null;
    });
}
