import { useEffect, useRef } from 'react';
import { useDispatch } from 'react-redux';
import { BrowserRouter, Route, Routes } from 'react-router-dom';
import { ToastContainer } from 'react-toastify';

import { fetchUserDataApi } from './api/authApi';
import { RegularUser } from './components/user/profile/RegularUser/RegularUser';
import { AffiliateProgram } from './pages/AffiliateProgram';
import { Connect } from './pages/Connect';
import { Home } from './pages/Home';
import { Safety } from './pages/Safety';
import { Strategies } from './pages/Strategies/Strategies';
import { Technologies } from './pages/Technologies';
import { Trades } from './pages/Trades';
import { fetchLoginSuccess, logout } from './redux/slices/loginSlice';
import { PrivateRoute } from './utils/PrivateRoute';
import { CalcWindow, DashboardHeader } from './widgets';

import './index.css';

function App() {
  const dispatch = useDispatch();

  const testRef = useRef(null);

  /*useScrollTriggerProxy();*/

  useEffect(() => {
    const checkToken = async () => {
      const token = localStorage.getItem('token');
      const user = localStorage.getItem('user');
      if (token && user) {
        try {
          const { data, status } = await fetchUserDataApi(JSON.parse(user).id);
          if (status === 200) {
            dispatch(fetchLoginSuccess({ user: JSON.parse(user), token }));
          } else {
            // Токен невалиден или истёк
            dispatch(logout());
          }
        } catch (e) {
          dispatch(logout());
        }
      } else {
        dispatch(logout());
      }
    };

    checkToken();
  }, [dispatch]);

  return (
    <>
      {/*<StockBackground /> {/* Фон */}

      <BrowserRouter>
        <DashboardHeader />
        <Routes>
          {/* Главная страница с секциями */}
          <Route
            path="/"
            element={
              <div className="main-conteiner">
                {/* Полоса вверху экрана */}
                {/*<div className="top-line" />*/}
                <section id="home">
                  <Home />
                </section>
                <section id="trades">
                  <Trades />
                </section>
                <section id="strategies">
                  <Strategies />
                </section>
                <section id="technologies">
                  <Technologies />
                </section>
                <section id="safety">
                  <Safety />
                </section>
                <section id="сonnect">
                  <Connect />
                </section>
                <section id="affiliateProgram">
                  <AffiliateProgram />
                </section>
              </div>
            }
          />

          {/* Отдельные страницы */}
          {/*<Route
            path="/profile"
            element={
              logged_in_user["isSuperUser"] === 1 ? (
                <SuperUser />
              ) : (
                <RegularUser />
              )
            }
          />*/}
          {/*<Route path="/login" element={<LoginForm />} />
          <Route path="/register" element={<Register />} />*/}
          <Route element={<PrivateRoute />}>
            <Route path="/profile" element={<RegularUser />} />
          </Route>
        </Routes>

        <ToastContainer />
        {/*<CalcWindow />*/}
      </BrowserRouter>
    </>
  );
}

export default App;
