import { useEffect, useState } from 'react';

import { fetchUserDataApi } from '../../api/authApi';
import { fetchBTCYearData } from '../../api/tradingApi';
import { Tracker } from '../../components/user/sections/components/Tracker';
import { IndexString } from '../../components/widget/indexString';
import { formatBTCData } from '../../utils/utils';

import styles from './Trades.module.css';

export const Trades = () => {
  const [viewSelector, setViewSelector] = useState('График');
  const [timeframeSelector, setTimeframeSelector] = useState('День');
  const [accountData, setAccountData] = useState(null);
  const [bitcoinData, setBitcoinData] = useState(null);

  const userId = 1;

  useEffect(() => {
    if (!userId) return;

    // Первый запрос
    fetchUserDataApi(userId).then((data) => setAccountData(data));

    // Интервал
    const interval = setInterval(() => {
      fetchUserDataApi(userId).then((data) => setAccountData(data));
    }, 5000000);

    return () => clearInterval(interval);
  }, [userId]);

  useEffect(() => {
    fetchBTCYearData(userId).then((rawData) => {
      const btcArray = rawData?.Data?.Data || [];
      const formatted = formatBTCData(btcArray);
      setBitcoinData(formatted.slice(-365));
    });
  }, []);

  return (
    <>
      <div className={styles.container}>
        <div className={styles.header}>
          <h1 className={styles.title}>Трейды</h1>
        </div>
        <IndexString accountData={accountData} />
        <div className={styles.infoBlock}>
          <Tracker id={userId} pageType={'mainPage'} height={395} additionalData={bitcoinData} />
        </div>
      </div>
    </>
  );
};
